effects.preApplyScript:
if (this.actor.system.status.advantage.value >= 2)
{
    await this.actor.setAdvantage(0);
    this.script.scriptNotification("Advantage Subtracted")
    return true;
}
else 
{
    this.script.scriptNotification("Not enough Advantage!", "error")
    return false;
}

scriptData.script:
let avoidTest = await args.actor.setupSkill("Dodge")

await avoidTest.roll()
if (avoidTest.result.outcome == "failure")
{
    let damage = (await new Roll("2d10").roll()).total
    await args.actor.applyBasicDamage(damage)

    let poisonedTest = await args.actor.setupSkill(game.i18n.localize("NAME.Endurance"))
    await poisonedTest.roll()
   if (poisonedTest.result.outcome == "failure")
   {
       args.actor.addCondition("poisoned", 2)
   }

}

